<script setup>import {useCuttingStore} from '../stores/cutting.js';const store=useCuttingStore();defineEmits(['reset']);</script>
<template><nav class="mcpv-nav" aria-label="Navigation entre plaques"><button aria-label="Plaque précédente" :disabled="store.sheetIndex===0" @click="store.setSheet(store.sheetIndex-1)">‹</button><select aria-label="Choisir une plaque" :value="store.sheetIndex" @change="store.setSheet(Number($event.target.value))"><option v-for="(sheet,i) in store.sheets" :key="i" :value="i">Plaque {{i+1}} / {{store.sheets.length}} · {{sheet.serial_no||sheet.label||''}}</option></select><button aria-label="Plaque suivante" :disabled="store.sheetIndex>=store.sheets.length-1" @click="store.setSheet(store.sheetIndex+1)">›</button><button aria-label="Annuler la dernière modification" title="Annuler la dernière modification (Ctrl/Cmd + Z)" :disabled="!store.canUndo" @click="store.undo()">↶ Annuler</button><button aria-label="Rétablir la modification" title="Rétablir la modification (Ctrl/Cmd + Maj + Z)" :disabled="!store.canRedo" @click="store.redo()">↷ Rétablir</button><span class="mcpv-dimensions">{{store.sheet?.length_mm}} × {{store.sheet?.width_mm}} mm</span><button aria-label="Zoom arrière" @click="store.setZoom(store.zoom-.25)">−</button><button aria-label="Zoom avant" @click="store.setZoom(store.zoom+.25)">+</button><button aria-label="Ajuster à l’écran" @click="store.fit()">⤢</button><button aria-label="Centrer sur la sélection" :disabled="!store.selected" @click="store.focusSelection()">◎</button><span class="mcpv-nav-actions"><button class="mcpv-warning" :disabled="store.locked||store.compensationOpen||store.isSaving" @click="$emit('reset')">↺ Réinitialiser</button><button v-if="store.canCompensate||store.compensationOpen" :disabled="store.compensationOpen" @click="store.openCompensation">Compenser</button></span></nav></template>

<style>.mcpv-nav-actions{display:flex;gap:6px;flex-shrink:0}</style>
